<?php
require_once 'includes/db.php';require_once 'includes/functions.php';require_admin();$pageTitle='Reports';require 'includes/header.php';
$studentCount=(int)$conn->query('SELECT COUNT(*) n FROM student')->fetch_assoc()['n'];$courseCount=(int)$conn->query('SELECT COUNT(*) n FROM course')->fetch_assoc()['n'];$paid=(float)$conn->query('SELECT COALESCE(SUM(amount),0) n FROM payment')->fetch_assoc()['n'];$registrations=(int)$conn->query('SELECT COUNT(*) n FROM registration')->fetch_assoc()['n'];
?>
<div class="page-heading"><div><h1>Reports</h1><p class="subheading">Summary reports from the current MIU database records.</p></div><button class="btn secondary" onclick="window.print()">Print report</button></div><div class="stats"><div class="stat"><div class="stat-label">Total students</div><div class="stat-value"><?= $studentCount ?></div></div><div class="stat"><div class="stat-label">Total courses</div><div class="stat-value"><?= $courseCount ?></div></div><div class="stat"><div class="stat-label">Registrations</div><div class="stat-value"><?= $registrations ?></div></div><div class="stat"><div class="stat-label">Payments recorded</div><div class="stat-value">UGX <?= number_format($paid) ?></div></div></div>
<div class="report-grid"><div class="card"><h2>Students by course</h2><div class="table-wrap"><table><thead><tr><th>Course</th><th>Students</th></tr></thead><tbody><?php $r=$conn->query('SELECT c.course_title,COUNT(s.student_id) total FROM course c LEFT JOIN student s ON s.course_id=c.course_id GROUP BY c.course_id,c.course_title ORDER BY total DESC');while($row=$r->fetch_assoc()): ?><tr><td><?= e($row['course_title']) ?></td><td><?= (int)$row['total'] ?></td></tr><?php endwhile; ?></tbody></table></div></div><div class="card"><h2>Payments by fee type</h2><div class="table-wrap"><table><thead><tr><th>Fee type</th><th>Total paid (UGX)</th></tr></thead><tbody><?php $r=$conn->query('SELECT f.fee_name,COALESCE(SUM(p.amount),0) total FROM fee_type f LEFT JOIN payment p ON p.fee_type_id=f.fee_type_id GROUP BY f.fee_type_id,f.fee_name ORDER BY total DESC');while($row=$r->fetch_assoc()): ?><tr><td><?= e($row['fee_name']??'Unnamed fee') ?></td><td><?= number_format((float)$row['total']) ?></td></tr><?php endwhile; ?></tbody></table></div></div></div>
<div class="card"><h2>Recent payments</h2><div class="table-wrap"><table><thead><tr><th>Payment ID</th><th>Student</th><th>Fee type</th><th>Amount (UGX)</th><th>Date</th><th>Method</th><th>Reference</th></tr></thead><tbody><?php $r=$conn->query('SELECT p.payment_id,s.reg_no,f.fee_name,p.amount,p.payment_date,p.method,p.reference_no FROM payment p JOIN student s ON s.student_id=p.student_id JOIN fee_type f ON f.fee_type_id=p.fee_type_id ORDER BY p.payment_date DESC,p.payment_id DESC LIMIT 100');while($row=$r->fetch_assoc()): ?><tr><td><?= (int)$row['payment_id'] ?></td><td><?= e($row['reg_no']) ?></td><td><?= e($row['fee_name']) ?></td><td><?= number_format((float)$row['amount']) ?></td><td><?= e($row['payment_date']) ?></td><td><?= e($row['method']) ?></td><td><?= e($row['reference_no']) ?></td></tr><?php endwhile; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>